export type Placement = {
  key: string;
  platform: string;
  name: string;
  width: number;
  height: number;
  /** Fractions of the frame covered by the platform's own interface. */
  safeTop: number;
  safeBottom: number;
  safeLeft: number;
  safeRight: number;
  maxMb: number;
  formats: string[];
  video: boolean;
  /** Field name to maximum characters, before the platform truncates silently. */
  textLimits: Record<string, number>;
  note: string;
};

