export type PolicyRule = {
  key: string;
  /** Source and flags, so the browser can rebuild the same expression. */
  pattern: string;
  flags: string;
  severity: "block" | "warn";
  /** The platform's own reasoning, so an advertiser can argue with it. */
  why: string;
  fix: string;
  platforms: string[];
};

export const POLICY_RULES: PolicyRule[] = [
  { key: "personal_attributes", pattern: "\\b(are you|do you (?:have|suffer|struggle)|struggling with|suffering from|your (?:diabetes|debt|depression|anxiety|divorce|bankruptcy|addiction|weight problem|hair loss))\\b", flags: "i", severity: "block", why: "Meta prohibits copy asserting or implying knowledge of a reader's personal characteristics: health, finances, race, religion, sexual orientation or criminal record. Google has the same rule for personalised advertising. It is the single most common disapproval in health and finance.", fix: "Write about the product rather than the reader. “Struggling with debt?” becomes “Debt consolidation from 4.9 per cent”, which says the same thing to the right person and accuses nobody.", platforms: ["meta_ads", "google_ads", "tiktok_ads"] },
  { key: "guaranteed_outcome", pattern: "\\b(guaranteed?|100% (?:success|effective|safe)|risk[- ]free|cure[sd]?|miracle|permanent(?:ly)? (?:cure|fix))\\b", flags: "i", severity: "block", why: "An unqualified guarantee of a result is prohibited across every major network, and in health, finance and legal it also attracts a regulator.", fix: "Say what is actually promised. “Guaranteed results” becomes “30-day money back”, which is a guarantee you can keep.", platforms: [] },
  { key: "unrealistic_earnings", pattern: "(\u00a3|\\$|\u20ac)\\s?\\d[\\d,]*(?:k|,000)?\\s*(?:a|per|/)\\s*(?:day|week|month)|make money fast|get rich", flags: "i", severity: "block", why: "Income claims need substantiation and a disclaimer, and on Meta most are refused outright under the misleading claims policy.", fix: "Drop the figure, or replace it with a verifiable customer outcome and name the customer.", platforms: [] },
  { key: "before_after", pattern: "\\bbefore (?:and|&|/) after\\b|\\bresults? in \\d+ days?\\b|\\btransformation\\b", flags: "i", severity: "warn", why: "Before and after imagery is prohibited in health and fitness on Meta, and the phrase in copy usually accompanies the image that will be rejected.", fix: "Show the process or the product rather than a body comparison.", platforms: ["meta_ads", "tiktok_ads"] },
  { key: "excessive_caps", pattern: "\\b[A-Z]{5,}\\b", flags: "", severity: "warn", why: "Gratuitous capitals are grounds for disapproval on Google and reduce delivery on Meta. An acronym is fine; a shouted word is not.", fix: "Sentence case. If a word needs emphasis, the offer is not strong enough.", platforms: [] },
  { key: "excessive_punctuation", pattern: "[!?]{2,}|!.*!", flags: "", severity: "warn", why: "More than one exclamation mark in an ad is a Google editorial disapproval, stated in their published policy.", fix: "One at most, and usually none.", platforms: [] },
  { key: "false_urgency", pattern: "\\b(?:only )?\\d+ (?:spots?|places?|left)\\b|\\blast chance\\b|\\bends (?:today|tonight|in \\d+ hours?)\\b", flags: "i", severity: "warn", why: "Urgency that is not true is a misrepresentation, and platforms increasingly check it against the landing page. A countdown that resets on refresh is an enforcement action waiting to happen.", fix: "Only use it where the deadline is real and appears on the page. Otherwise cut it.", platforms: [] },
  { key: "competitor_trademark", pattern: "\\b(?:better than|cheaper than|vs\\.?|versus|alternative to)\\s+[A-Z][A-Za-z0-9]+", flags: "i", severity: "warn", why: "A competitor's trademark in ad text can be removed on a complaint. Bidding on the term is usually allowed; putting it in the headline usually is not.", fix: "Keep the term as a keyword and take the brand name out of the copy.", platforms: [] },
  { key: "clickbait", pattern: "\\b(?:you won'?t believe|doctors hate|one weird trick|shocking|this changes everything)\\b", flags: "i", severity: "block", why: "Sensational copy is explicitly listed under Meta's low quality policy and suppresses delivery even where it is not rejected.", fix: "Say the actual thing. It performs better anyway.", platforms: [] },
  { key: "health_claim", pattern: "\\b(?:treats?|prevents?|reverses?|heals?)\\s+\\w+|\\bFDA[- ]approved\\b|\\bclinically proven\\b", flags: "i", severity: "warn", why: "A medical claim needs evidence and, in the UK, compliance with the advertising codes. Platforms route these to manual review, which delays a launch by days.", fix: "Soften to what can be evidenced, and keep the evidence to hand for the review.", platforms: [] },
  { key: "personal_data_request", pattern: "\\b(?:enter your|send us your)\\s+(?:card|bank|passport|national insurance|social security)\\b", flags: "i", severity: "block", why: "Soliciting sensitive personal or financial details in an advert is prohibited everywhere and is a fast route to an account ban.", fix: "Collect nothing sensitive in an ad or a lead form. Move it behind a verified account.", platforms: [] },
];

